// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ERCDDAToken} from "../src/ERCDDAToken.sol";

contract InvMutTest is Test {
    ERCDDAToken c;
    function setUp() public { c = new ERCDDAToken(0, "", ""); }
    function testFuzz_property(uint256 _value, address _caller) public {
        vm.assume(_caller != address(0));
        vm.assume(_caller != c.owner());
        vm.assume(_value > 0 && _value <= type(uint256).max / 2);

        vm.prank(c.owner());
        c.mintToken(_caller, _value);

        vm.prank(_caller);
        bool ok = true;
        try c.burn(_value) { ok = true; } catch { ok = false; }

        assertTrue(!ok, "non-owner burn should revert");
    }
}
